// Se saca el token y se guarda el cuerpo para despues.
const cab = $json.headers || {};
const auth = String(cab.authorization || cab.Authorization || '');
const token = auth.startsWith('Bearer ') ? auth.slice(7).trim() : '';

return [{ json: {
  token,
  hay_cabecera: auth.length > 0,
  body: $json.body || {},
} }];

// Supabase es la autoridad. Comprobado empiricamente:
//   token real           -> 200 + el usuario
//   token inventado      -> 403
//   sin token            -> 403
//   exp manipulado       -> 403  (cambiar el payload rompe la firma)

const r = $json || {};
const codigo = r.statusCode || 0;
let cuerpo = r.body;
if (typeof cuerpo === 'string') { try { cuerpo = JSON.parse(cuerpo); } catch (e) {} }

const previo = $('Sacar el token').first().json;

let valido = false;
let motivo = "";

if (!previo.hay_cabecera) {
  motivo = "falta la cabecera Authorization";
} else if (!previo.token) {
  motivo = "la cabecera no es del tipo Bearer";
} else if (codigo !== 200) {
  motivo = "sesión no válida o caducada (Supabase devolvió " + codigo + ")";
} else if (!cuerpo || !cuerpo.id) {
  motivo = "Supabase respondió 200 pero sin usuario";
} else if (cuerpo.role !== 'authenticated') {
  motivo = "el usuario no tiene rol authenticated";
} else {
  valido = true;
}

return [{ json: {
  veredicto: valido ? 'ok' : 'no',
  motivo,
  usuario_id: (cuerpo && cuerpo.id) || null,
  usuario_email: (cuerpo && cuerpo.email) || null,
  body: previo.body,
} }];

// Ya sabemos QUIEN envia. Ahora se valida QUE envia.
const b = $json.body || {};
const MENSAJES = ['texto', 'imagen', 'documento', 'audio', 'video'];
const BLOQUEO  = ['bloquear', 'desbloquear'];
const ACCIONES = MENSAJES.concat(BLOQUEO);

const esBloqueo = BLOQUEO.includes(b.accion);

const fallos = [];
if (!b.cliente_id) fallos.push('falta cliente_id');
if (!ACCIONES.includes(b.accion)) fallos.push('accion no valida: ' + b.accion);
if (b.accion === 'texto' && !b.texto) fallos.push('texto vacio');
if (MENSAJES.includes(b.accion) && b.accion !== 'texto' && !b.media_url) fallos.push('falta media_url');

// Limites de la Cloud API. El inbox ya avisa ANTES de subir, pero esto es
// la red de seguridad: si algo se cuela, mejor un 400 nuestro que gastar
// una llamada a Meta para que la rechace ella.
const LIMITES = { imagen: 5, video: 16, audio: 16, documento: 100 };
const mb = Number(b.tamano || 0) / 1048576;
if (LIMITES[b.accion] && mb > LIMITES[b.accion]) {
  fallos.push('el fichero pesa ' + mb.toFixed(1) + ' MB y el limite de ' +
              b.accion + ' son ' + LIMITES[b.accion] + ' MB');
}

if (fallos.length) {
  return [{ json: { error_peticion: fallos.join(' · ') } }];
}

return [{ json: {
  accion: b.accion,
  es_bloqueo: esBloqueo ? 'si' : 'no',
  cliente_id: String(b.cliente_id),
  texto: b.texto || '',
  media_url: b.media_url || null,
  // Nombre real del fichero: WhatsApp lo enseña como titulo del documento.
  // Sin el, al cliente le llega un PDF llamado "1787391234-algo.pdf".
  nombre_fichero: b.nombre_fichero || null,
  tamano: b.tamano || null,
  miniatura_url: b.miniatura_url || null,
  // Siempre humano: lo que sale del inbox lo escribe una persona.
  autor: 'humano',
  enviado_por: $json.usuario_email,
} }];

const p = $('Validar y traducir').first().json;
const r = $json || {};
const codigo = r.statusCode || 0;
let cuerpo = r.body;
if (typeof cuerpo === 'string') { try { cuerpo = JSON.parse(cuerpo); } catch (e) {} }

const quiere = p.accion === 'bloquear';
const bu = (cuerpo && cuerpo.block_users) || {};
// Bloquear devuelve added_users; desbloquear, removed_users.
const hechos   = (quiere ? bu.added_users : bu.removed_users) || [];
const fallidos = bu.failed_users || [];

const ok = codigo >= 200 && codigo < 300 && hechos.length > 0;

let error = null;
if (!ok) {
  const e = fallidos[0] && fallidos[0].errors && fallidos[0].errors[0];
  if (e && e.code === 131047) {
    // El caso normal, y el unico que el equipo va a ver de verdad.
    error = 'WhatsApp solo deja bloquear a quien te haya escrito en las ultimas 24 h. Este cliente lleva mas tiempo sin escribir.';
  } else if (e && e.code === 139101) {
    error = 'La lista de bloqueados esta llena (64.000). Hay que quitar a alguien antes.';
  } else if (e) {
    error = e.message + ((e.error_data && e.error_data.details) ? ': ' + e.error_data.details : '');
  } else if (cuerpo && cuerpo.error) {
    error = cuerpo.error.message || JSON.stringify(cuerpo.error).slice(0, 200);
  } else {
    error = 'Meta respondio ' + codigo;
  }
}

// El PATCH solo toca `bloqueada` si Meta ha dicho que si. Si falla, se
// guarda el motivo y la columna se queda como estaba: la base de datos
// no puede decir "bloqueada" de alguien que sigue pudiendo escribirte.
const patch = ok
  ? { bloqueada: quiere, bloqueada_en: quiere ? new Date().toISOString() : null, bloqueo_nota: null }
  : { bloqueo_nota: error };

return [{ json: { ok, error, cliente_id: p.cliente_id, patch } }];
